import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

// src/styles/tanaw-tokens.css and src/design-system/** are generated by design-system/scripts/sync.mjs.
// This app never imports from design-system/; the source checks only run when the whole repository
// is checked out.
const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../..");
const repoRoot = path.resolve(appRoot, "..");
const kitCopyDir = path.join(appRoot, "src/design-system");
const kitSourceDir = path.join(repoRoot, "design-system/src");
const tokenCopy = path.join(appRoot, "src/styles/tanaw-tokens.css");
const tokenSource = path.join(repoRoot, "design-system/tokens/tanaw.css");
const HEADER_END = "\n */\n";
const SYNC = "node design-system/scripts/sync.mjs";
const COPIED = /\.(ts|tsx|css)$/;
const EXCLUDED = /\.(stories|test|spec)\.(ts|tsx)$/;

const normalize = (text: string) => text.replace(/\r\n/g, "\n");
const sha256 = (text: string) => createHash("sha256").update(normalize(text), "utf8").digest("hex");

function listFiles(dir: string, base = dir): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? listFiles(full, base) : [path.relative(base, full).split(path.sep).join("/")];
  });
}

function readCopy(file: string) {
  const text = normalize(readFileSync(file, "utf8"));
  const recorded = /Source SHA-256: ([0-9a-f]{64})/.exec(text)?.[1];
  const end = text.indexOf(HEADER_END);
  return { recorded, body: end < 0 ? "" : text.slice(end + HEADER_END.length) };
}

const copies = [tokenCopy, ...listFiles(kitCopyDir).map((rel) => path.join(kitCopyDir, rel))];

describe("design system copies", () => {
  it("exist", () => {
    expect(existsSync(tokenCopy)).toBe(true);
    expect(listFiles(kitCopyDir).length).toBeGreaterThan(0);
  });

  it.each(copies.map((file) => [path.relative(appRoot, file), file]))("%s was not edited by hand", (_name, file) => {
    const { recorded, body } = readCopy(file);
    expect(recorded, `${file} is missing its generated header; run ${SYNC}`).toBeDefined();
    expect(sha256(body), `${file} was edited; change the design-system/ source and run ${SYNC}`).toBe(recorded);
  });

  it.skipIf(!existsSync(tokenSource))("tokens match design-system/tokens/tanaw.css", () => {
    expect(readCopy(tokenCopy).recorded, `the token copy is stale; run ${SYNC}`).toBe(sha256(readFileSync(tokenSource, "utf8")));
  });

  it.skipIf(!existsSync(kitSourceDir))("components match design-system/src, with nothing missing or left over", () => {
    const sources = listFiles(kitSourceDir).filter((rel) => COPIED.test(rel) && !EXCLUDED.test(rel)).sort();
    expect(listFiles(kitCopyDir).sort(), `copies differ from design-system/src; run ${SYNC}`).toEqual(sources);
    for (const rel of sources) {
      expect(readCopy(path.join(kitCopyDir, rel)).recorded, `${rel} is stale; run ${SYNC}`).toBe(sha256(readFileSync(path.join(kitSourceDir, rel), "utf8")));
    }
  });
});
